def change(id,place,c,h,final,evidence,confidence='high',kind='misread word',ac=False,ah=True,consequential=False,box=None):
    crop=id.split('_')[0]
    cats={'misread word':2,'misread symbol or index':1,'omission':3,'drawing or diagram':4,'readable ink left as \\ill{}':5,'insertion or placement':6,'deletion state (struck given live or live given struck)':7,'abbreviation expanded or spelling modernised':8,'text not on the page':9,'other':10}
    R['changes'].append({'id':id,'place':place,'c':c,'h':h,'final':final,'evidence':evidence,'crop':f'crops/150_scan004_{crop}.png','box':box or boxes[crop],'confidence':confidence,'kind':kind,'against_c':ac,'against_h':ah,'marked_in_h':any(s in h for s in [r'\uncertain',r'\ill',r'\supplied']),'consequential':consequential,'error_category':cats[kind]})

